#!/usr/bin/env python3
"""Genera guías S2–S8 y decks S8. S1–S7 usan build-editorial.py."""
from pathlib import Path
import html,json
ROOT=Path(__file__).resolve().parents[1]
esc=lambda s:html.escape(str(s),quote=True)
def links(data):return ' · '.join(f'<a href="{esc(u)}" target="_blank" rel="noopener">{esc(t)} ↗</a>' for t,u in data)
def demo(kind):
 if kind=='join-types':return '<div class="demo" data-join-types><div class="demo-head"><span>DOS PERSONAS · SOLO ANA TIENE SALARIO COINCIDENTE</span><button data-join-types-toggle aria-pressed="false">Usar LEFT JOIN</button></div><div class="join-rows"><div>10001 · Ana · salario 60000</div><div class="unmatched" hidden>10002 · Luis · salario NULL (sin coincidencia)</div></div><p class="demo-answer" role="status">INNER JOIN: solo Ana tiene una coincidencia. Luis no aparece en el resultado.</p></div>'
 if kind=='join':return '''<div class="demo join-demo" data-join><div class="demo-head"><span>EJEMPLO ILUSTRATIVO · PERSONA 10001</span><button data-join-toggle aria-pressed="false">Filtrar salario vigente</button></div><div class="join-rows"><div>10001 · salario 40000 · hasta 1995</div><div>10001 · salario 45000 · hasta 1996</div><div>10001 · salario 60000 · vigente en snapshot</div></div><p class="demo-answer" role="status">Tres filas salariales, una persona. No es un conteo de empleados actuales.</p></div>'''
 if kind=='quality':return '''<div class="demo" data-quality><div class="demo-head"><span>FIXTURE ILUSTRATIVO · RECONCILIACIÓN</span><button data-quality-toggle aria-pressed="false">Aplicar reglas</button></div><div class="quality-ledger"><b>16<small>Entrada</small></b><span>=</span><b>1<small>Copia</small></b><span>+</span><b>2<small>Rechazadas</small></b><span>+</span><b>13<small>Aceptadas</small></b></div><p class="demo-answer" role="status">Antes de transformar: conservar el original y su conteo.</p></div>'''
 if kind in ['basket','dashboard']:return '''<div class="demo" data-basket><div class="demo-head"><span>FIXTURE · 5 PRODUCTOS · 2024-01-15 · MXN</span><button data-basket-toggle aria-pressed="false">Exigir cobertura completa</button></div><div class="mini-bars"><div><b>A</b><span style="--w:94%">150</span><small>5/5</small></div><div><b>B</b><span style="--w:100%">160</span><small>5/5</small></div><div class="incomplete"><b>C</b><span style="--w:34%">54</span><small>3/5</small></div></div><p class="demo-answer" role="status">54 es un subtotal incompleto; no es costo de una canasta de cinco productos.</p></div>'''
 if kind=='retrieval':return '''<div class="demo" data-retrieval><div class="demo-head"><span>RECUPERACIÓN LOCAL · SIN LLM NI API</span><a href="practica.html" target="_blank" rel="noopener">Abrir práctica completa ↗</a></div><label>Buscar en fichas del fixture<input data-search placeholder="Ej. cobertura o inventario" maxlength="150"></label><button data-search-button>Recuperar fichas</button><p class="demo-answer" role="status">Inspecciona IDs y evidencia antes de pasar fragmentos al modelo.</p><div data-search-results class="search-summary"></div></div>'''
 if kind=='timer':return '''<div class="demo" data-timer><div class="demo-head"><span>DEFENSA 7 MIN + PREGUNTAS 3 MIN · INICIO MANUAL</span></div><output class="timer-value" aria-live="off">07:00</output><div class="timer-controls"><button data-timer-start>Iniciar / pausar</button><button data-timer-reset>Reiniciar</button><button data-timer-questions>Preguntas · 3 min</button></div></div>'''
 if kind=='rubric':return '''<div class="demo rubric-preview"><b>20</b> valor · <b>20</b> arquitectura · <b>25</b> SQL/calidad<br><b>20</b> comunicación · <b>10</b> GenAI · <b>5</b> reproducibilidad<p>Propuesta de 100 puntos. <a href="../recursos/rubrica.csv" download>Descargar rúbrica ↓</a></p></div>'''
 return ''
def body(s):
 kind=s['kind'];items=s['items']
 if kind=='code':
  return '<div class="code-lesson"><div>'+''.join(f'<p data-step="{i}"><b>{esc(p["label"])}</b><br>{esc(p["text"])}</p>' for i,p in enumerate(items))+'</div><div class="code-panel"><span>FRAGMENTO DOCENTE · ARCHIVO COMPLETO EN LA GUÍA</span><pre tabindex="0"><code id="code-'+s['id']+'">'+esc(s['code'])+'</code></pre><button data-copy="code-'+s['id']+'">Copiar código</button><span class="copy-status" role="status"></span></div></div>'
 if kind in ['join','join-types','quality','basket','dashboard','retrieval','timer','rubric']:
  return '<p class="interaction-intro">'+esc(items[0]['text'])+'</p>'+demo(kind)+f'<p class="takeaway" data-step="1"><strong>{esc(items[1]["label"])}:</strong> {esc(items[1]["text"])}</p>'
 if kind=='pause':return '<div class="pause-number">10<span>MINUTOS</span></div>'+''.join(f'<p class="lead" data-step="{i}">{esc(x["text"])}</p>' for i,x in enumerate(items))
 if kind=='cover':return '<p class="lead">'+esc(items[0]['text'])+'</p><div class="session-number" aria-hidden="true">'+s['id'][1:3]+'</div><p class="takeaway" data-step="1"><strong>'+esc(items[1]['label'])+':</strong> '+esc(items[1]['text'])+'</p>'
 if kind=='flow':
  nodes=s['nodes']
  return '<div class="journey">'+''.join(('<b aria-hidden="true" data-step="%d">→</b>'%i if i else '')+f'<div data-step="{i}">{a}<small>{b}</small></div>' for i,(a,b) in enumerate(nodes))+'</div><p class="caption">'+esc(items[0]['text'])+'</p><p class="takeaway" data-step="2"><strong>'+esc(items[1]['label'])+':</strong> '+esc(items[1]['text'])+'</p>'
 return '<div class="lesson-panels '+('contrasted' if kind=='contrast' else '')+'">'+''.join(f'<article data-step="{i}"><span class="tag">{esc(x["label"])}</span><p>{esc(x["text"])}</p></article>' for i,x in enumerate(items))+'</div>'
def shell(title,inner,n):
 return f'''<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="Especialidad, sesión {n}: {esc(title)}"><title>{esc(title)} · Especialidad</title><link rel="stylesheet" href="../compartido/curso.css"><script src="../compartido/deck.js" defer></script></head><body data-session="{n}"><header><a class="brand" href="../"><span class="mark" aria-hidden="true">∴</span> Big Data <span class="edition">ESPECIALIDAD / {n:02d}</span></a><nav aria-label="Herramientas"><button id="index-button">Índice <kbd>O</kbd></button><button id="lab-button">Guía de laboratorio</button><button id="fullscreen" aria-label="Pantalla completa">⛶</button></nav></header><main id="stage" aria-label="Presentación; clic en espacio libre para avanzar">{inner}</main><footer><div><span id="counter" class="counter"></span><span id="step-counter" class="step-counter" aria-live="polite"></span></div><div class="footer-middle"><span id="section-label"></span><small>Clic o → revela · ← retrocede</small></div><div class="controls"><button id="show-all">Mostrar todo</button><button id="notes-button">Notas</button><button id="previous" aria-label="Paso anterior">←</button><button id="next" aria-label="Paso siguiente">→</button></div></footer><div class="progress" aria-hidden="true"><div id="progress"></div></div><dialog id="overview"><div class="dialog-heading"><h2>Ruta de la sesión {n}</h2><button data-close>Cerrar ×</button></div><ol id="slide-list"></ol><button id="print-button">Imprimir todas las slides</button></dialog><dialog id="notes"><div class="dialog-heading"><h2>Notas de facilitación</h2><button data-close>Cerrar ×</button></div><p id="notes-text"></p></dialog><dialog id="lab"><div class="dialog-heading"><h2>Laboratorio / taller</h2><button data-close>Cerrar ×</button></div><p>Abre las instrucciones sin perder tu lugar.</p><a href="laboratorio.html" target="_blank" rel="noopener">Guía completa y recursos ↗</a></dialog><noscript>Activa JavaScript para las interacciones. El contenido y la guía permanecen legibles.</noscript><script type="application/json" id="corpus-inline">{(ROOT/'recursos/corpus-evidencia.json').read_text()}</script></body></html>'''
def phase(n,i):
 if n==8:return 'COMITÉ · '+('ENCUADRE' if i<=8 else 'DEFENSAS / AUDITORÍA / CIERRE')
 return 'APERTURA · 0–15 MIN' if i<=3 else 'CONCEPTOS · 15–45 MIN' if i<=11 else 'CASOS / DEMO · 45–65 MIN' if i<=15 else 'PAUSA · 65–75 MIN' if i==16 else 'LABORATORIO · 75–130 MIN' if i<=23 else 'PROYECTO PROPIO · 130–160 MIN' if i<=26 else 'CIERRE · 160–180 MIN'
def render(data,path):
 n=data['session'];ss=[]
 for i,s in enumerate(data['slides'],1):
  resource=''
  if 17<=i<=23 or (n==8 and i>=9):resource='<p class="source"><a href="laboratorio.html#paso-'+str(max(1,i-17))+'" target="_blank" rel="noopener">Instrucciones, código completo, comprobación y recuperación ↗</a></p>'
  if s.get('sources'):resource='<p class="source">'+links(s['sources'])+'</p>'
  ss.append(f'<section class="slide kind-{s["kind"]}" data-id="{s["id"]}" data-title="{esc(s["title"])}" data-note="{esc(s["note"])}"><div class="eyebrow">SESIÓN {n:02d} / {phase(n,i)}<span>ESPECIALIDAD · H{n}</span></div><h1>{esc(s["title"])}</h1>{body(s)}{resource}</section>')
 if n >= 8:
  (path/'index.html').write_text(shell(data['title'],'\n'.join(ss),n))
 assets='<ul>'+''.join(f'<li><a href="../recursos/{esc(a)}" download>{esc(a)} ↓</a></li>' for a in data['assets'])+'</ul>'
 steps=''
 for step in data['lab']['steps']:
  steps+=f'<section id="paso-{step["n"]}"><h2>Paso {step["n"]} · {step["minutes"]} min</h2><p><strong>Acción:</strong> {esc(step["action"])}</p><p><strong>Comprobación y recuperación:</strong> {esc(step["check"])}</p></section>'
 if n==8:
  actions=['Comprobar paquete y respaldo local','Defender problema, evidencia y recomendación','Responder grano, calidad, límites y costo','Auditar una cifra de otro equipo','Conservar archivos y probar accesos','Cerrar recursos según acuerdo con el docente']
  steps=''.join(f'<section id="paso-{i}"><h2>{i}. {a}</h2><p>Registrar evidencia en auditoria-proyecto.csv y revisar el paquete del proyecto propio. Si falta acceso, usar respaldo y señalar la limitación. No crear infraestructura nueva ni publicar crudos.</p></section>' for i,a in enumerate(actions,1))
 codeblocks=''
 if n in [2,3,4,5,6,7]:
  for a in data['assets']:
   if a.endswith(('.sql','.txt')):
    codeblocks+=f'<details><summary>{esc(a)} · ver contenido completo</summary><pre><code>{esc((ROOT/"recursos"/a).read_text())}</code></pre></details>'
 journal=f'''<section id="proyecto"><h2>Transferencia al proyecto propio · {'auditoría' if n==8 else '30 minutos'}</h2><p>Usa tu dataset distinto al de otros equipos. Conserva grano, reglas, fuente, KPI y límites de tu dominio. Las canastas y cifras ilustrativas no son un proyecto obligatorio. La preparación de cada paquete real debe validarse con el docente; no aplicar el esquema del fixture a cualquier archivo.</p><form id="journal-form"><label>Dataset y equipo<input name="dataset" maxlength="200" required></label><label>Evidencia del hito H{n}<textarea name="evidence" rows="3" maxlength="2000" required></textarea></label><label>Qué ejecuté / qué preparó el docente / qué falta<textarea name="limits" rows="3" maxlength="1500"></textarea></label><button type="submit">Descargar registro H{n} ↓</button><span id="journal-status" role="status"></span></form><p class="micro">Solo este navegador. La ficha no asigna fuentes ni envía una entrega. No escribir credenciales. Si localStorage falla, descargar el archivo.</p><a href="entregable.md" download>Plantilla del entregable ↓</a></section>'''
 practice='<p><a href="practica.html">Abrir recuperación local de evidencia ↗</a></p>' if n==7 else '<p><a href="practica.html">Abrir práctica local del dashboard ↗</a></p>' if n==6 else ''
 cloudtext=('<p><strong>Región propuesta:</strong> us-central1; verificar compatibilidad de GCS/BigQuery y política de cuenta. Leer los scripts antes de ejecutarlos en un proyecto de laboratorio: las escrituras reemplazan solo tablas curso_*. No apuntarlas a datos reales por un cambio de nombre improvisado.</p>' if 3<=n<=7 else '<p>Esta sesión no exige crear nueva infraestructura. Usar la conexión MariaDB preparada por el docente o el paquete ya construido, según corresponda.</p>')
 htmlguide=f'''<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Guía S{n} · {esc(data['title'])}</title><link rel="stylesheet" href="../compartido/curso.css"><script src="../compartido/journal.js" defer></script></head><body data-session="{n}"><article class="guide"><a href="index.html">← Volver al deck</a><p class="eyebrow">ESPECIALIDAD / S{n} · 180 MINUTOS</p><h1>{esc(data['title'])}</h1><p class="notice">Material local para revisión. Datos y resultados del fixture son ilustrativos: no provienen de filas de PROFECO ni demuestran escala. Los pasos cloud requieren cuenta, permisos, región y ensayo previo del docente. No se han ejecutado en GCP desde este sitio.</p><h2>Preparación, herramientas y ruta exacta</h2><p>{esc(data['lab']['instructions'])}</p><h2>Recursos completos descargables</h2>{assets}{practice}{cloudtext}{steps}<h2>Código completo y materiales</h2>{codeblocks}{journal}<section><h2>Entrega, costo y cierre</h2><p>Guardar consulta, versión de fuente, resultados/controles y límites; adjuntar el hito del dataset propio. Registrar bytes/job/caché o uso de modelo cuando corresponda. Cerrar la página no detiene recursos cloud. Conservar las capas necesarias para la siguiente sesión, revisar expiraciones/refrescos y detener cómputo de práctica según acuerdo; no borrar proyectos compartidos.</p><p>Si falta un paso anterior, usar el punto de restauración ilustrativo apropiado y decirlo. Esa recuperación no cuenta como ejecución real de una fuente grande ni del proyecto propio. No se exige entrenar ML.</p></section><h2>Fuentes</h2><p>{links(data['sources'])}</p><p>Consulta documental: 2026-11-05. Los casos reportan experiencias de sus publicadores; no garantizan el resultado del curso. Imprimir la guía con el navegador; el deck imprime todos los revelados desde su índice.</p><p><a href="notas-docente.md">Notas docentes</a> · <a href="../">Índice de sesiones</a></p></article></body></html>'''
 (path/'laboratorio.html').write_text(htmlguide)
 if n >= 8:
  (path/'notas-docente.md').write_text('# Notas docentes · '+data['title']+'\n\nEnsayar accesos y código por motor antes de clase. Solo Especialidad: sin entrenamiento de ML. Guía de 55 min + transferencia de 30 min (excepto S8 comité).\n\n'+'\n\n'.join('## '+s['id']+' · '+s['title']+'\n\n'+s['note'] for s in data['slides'])+'\n\n## Fuentes\n\n'+'\n'.join('- ['+t+']('+u+')' for t,u in data['sources'])+'\n')
 (path/'entregable.md').write_text(f'# H{n} · {data["title"]}\n\nEquipo y dataset propio:\nPregunta / audiencia:\nFuente y versión:\nGrano / periodo:\nConsulta o acción ejecutada:\nResultado y control:\nRegla / fórmula / denominador:\nEvidencia adjunta:\nQué preparó el docente:\nQué ejecutó el equipo:\nQué queda pendiente:\nCosto/bytes/servicio observado:\nAccesos y cierre:\nUna limitación y una mejora:\n\nNo entregar credenciales ni crudos sensibles. El fixture guiado es ilustrativo y no sustituye el proyecto con dataset propio. No hay modelo predictivo obligatorio.\n')
 if n >= 8:
  (path/'README.md').write_text(f'# Especialidad · S{n}: {data["title"]}\n\n{len(data["slides"])} slides y guía de laboratorio/taller. Abrir desde servidor sobre presentaciones-v2: /especialidad-{n:02d}/.\n\nFuente única: contenido.json. Regenerar HTML/guía/notas desde la raíz con `python3 presentaciones-v2/scripts/build.py`. No editar a mano el HTML generado. S1 y piloto no son regenerados.\n\nEl laboratorio usa recursos completos de ../recursos. Los datos ilustrativos no son filas de PROFECO ni evidencia de escala. Las guías cloud no se han ensayado end-to-end en una cuenta de alumno. El docente debe perfilar/adaptar cada paquete real distinto por equipo. No se exige ML técnico.\n\nVer README de la carpeta padre para navegación, límites y validación.\n')
 if n==7:
  practice=f'''<section class="slide kind-retrieval" data-title="Recuperar evidencia" data-note="Búsqueda local por palabras; no embeddings ni llamada LLM."><div class="eyebrow">PRÁCTICA S7<span>FIXTURE ILUSTRATIVO</span></div><h1>Recupera, inspecciona y después genera.</h1>{demo('retrieval')}<p class="source">Búsqueda por coincidencia de términos. Abrir la ficha antes de usar una cita. La generación ocurre aparte en la interfaz autorizada de GCP.</p></section>'''
  (path/'practica.html').write_text(shell('Recuperación local de evidencia',practice,n))
for n in range(2,9):
 p=ROOT/f'especialidad-{n:02d}';render(json.loads((p/'contenido.json').read_text()),p)
print('Generadas guías S2–S8 y decks S8. Ejecutar build-editorial.py después para notas y README S1–S7.')
